class TransferService {                       // one entry point
    std::mutex mu_;
public:
    void transfer(Account& from, Account& to, long cents) {
        const std::lock_guard<std::mutex> lock(mu_);   // acquired here
        from.withdraw(cents);
        to.deposit(cents);
    }                                                  // released here, even on throw
};

